atlas.onReady(() => {
  const tasks = Array.isArray(atlas.data.pendingTasks) ? atlas.data.pendingTasks : [];
  const today = new Date();
  today.setHours(0,0,0,0);

  const monday = new Date(today);
  monday.setDate(monday.getDate() - ((monday.getDay() + 6) % 7));
  const sunday = new Date(monday);
  sunday.setDate(sunday.getDate() + 6);

  const parseDate = value => {
    if (!value) return null;
    const date = new Date(value + 'T00:00:00');
    return Number.isNaN(date.getTime()) ? null : date;
  };
  const dayDiff = (a,b) => Math.round((a-b)/86400000);
  const weeksBetween = (later,earlier) => Math.max(0,Math.floor(dayDiff(later,earlier)/7));
  const orderValue = task => Number.isFinite(Number(task.order)) ? Number(task.order) : 9999;
  const priorityBoost = task => task.priority === 'high' ? 24 : task.priority === 'medium' ? 10 : 0;

  const bundles = new Map();

  tasks.forEach((task,index) => {
    const weekly = task.week !== undefined && task.week !== null;
    const key = weekly
      ? (task.moduleCode || 'UNKNOWN') + '::week::' + String(task.week)
      : (task.moduleCode || 'UNKNOWN') + '::standalone::' + String(index);

    if (!bundles.has(key)) {
      bundles.set(key,{
        key,
        moduleCode:task.moduleCode || 'UNKNOWN',
        week:weekly ? task.week : null,
        weekStart:weekly ? task.weekStart : null,
        tasks:[]
      });
    }
    bundles.get(key).tasks.push(task);
  });

  const rankBundle = bundle => {
    const weekly = bundle.week !== null;
    const sorted = [...bundle.tasks].sort((a,b) => {
      const ao=orderValue(a), bo=orderValue(b);
      if (ao !== bo) return ao-bo;
      if (a.required === b.required) return String(a.title||'').localeCompare(String(b.title||''));
      return a.required === true ? -1 : 1;
    });

    const urgent = sorted
      .map(task => ({task,due:parseDate(task.dueDate)}))
      .filter(x => x.due && dayDiff(x.due,today) <= 7)
      .sort((a,b) => a.due-b.due || orderValue(a.task)-orderValue(b.task));

    let selected;
    if (urgent.length) {
      selected=urgent[0].task;
    } else {
      selected=sorted.find(task => task.required === true) || sorted[0];
    }

    let score=0;
    const reasons=[];

    if (weekly) {
      const start=parseDate(bundle.weekStart);
      if (start) {
        if (start < monday) {
          const age=Math.max(1,weeksBetween(monday,start));
          score += 120 + Math.min(100, age*22);
          reasons.push('carry-over ' + age + (age===1 ? ' week' : ' weeks'));
        } else if (start <= sunday) {
          score += 105;
          reasons.push('current week');
        } else {
          const ahead=Math.max(1,weeksBetween(start,monday));
          score -= 70 + Math.min(50,ahead*12);
          reasons.push('future week');
        }
      }

      const unfinishedRequired=sorted.filter(task => task.required === true).length;
      score += Math.min(30, unfinishedRequired*5);

      const earlierRequired=sorted.filter(task =>
        task.required === true && orderValue(task) < orderValue(selected)
      ).length;

      if (earlierRequired > 0 && !urgent.length) {
        score -= earlierRequired*35;
      }

      if (!urgent.length && selected) reasons.push('next in course order');
    }

    const due=parseDate(selected && selected.dueDate);
    if (due) {
      const delta=dayDiff(due,today);
      if (delta < 0) {
        score += 190 + Math.min(45,-delta*3);
        reasons.unshift('overdue');
      } else if (delta <= 7) {
        score += 145 - delta*5;
        reasons.unshift('due in ' + delta + (delta===1 ? ' day' : ' days'));
      } else if (delta <= 21) {
        score += 65 - delta;
        reasons.push('deadline approaching');
      }
    }

    score += priorityBoost(selected || {});
    if (selected && selected.required === true) score += 15;
    if (selected && selected.required === false) score -= 12;

    if (!weekly) {
      if (!due) score += 30;
      if (selected && selected.required === true) score += 15;
    }

    return {
      bundle,
      task:selected,
      score,
      reasons:[...new Set(reasons)].filter(Boolean).slice(0,3)
    };
  };

  const ranked=[...bundles.values()]
    .map(rankBundle)
    .filter(entry => entry.task && entry.score > 0)
    .sort((a,b) =>
      b.score-a.score ||
      String(a.bundle.moduleCode).localeCompare(String(b.bundle.moduleCode)) ||
      orderValue(a.task)-orderValue(b.task)
    );

  const focus=ranked.slice(0,6);
  const stat=document.querySelector('#focus-stat strong');
  if (stat) stat.textContent=String(focus.length);

  const root=document.getElementById('focus-list');
  if (!root) return;
  root.textContent='';

  if (!focus.length) {
    const empty=document.createElement('atlas-empty-state');
    empty.setAttribute('title','Nothing urgent');
    empty.textContent='No current, carry-over or deadline-driven work needs attention.';
    root.append(empty);
    return;
  }

  focus.forEach((entry,index) => {
    const row=document.createElement('div');
    row.className='focus-item';

    const rank=document.createElement('span');
    rank.className='focus-rank';
    rank.textContent=String(index+1).padStart(2,'0');

    const main=document.createElement('div');
    main.className='focus-main';

    const strong=document.createElement('strong');
    strong.textContent=entry.task.title || 'Untitled task';

    const reason=document.createElement('div');
    reason.className='focus-reason';
    const prefix=entry.bundle.week !== null ? 'Week '+entry.bundle.week+' · ' : '';
    reason.textContent=prefix + (entry.reasons.join(' · ') || 'pending');

    main.append(strong,reason);

    const meta=document.createElement('div');
    meta.className='focus-meta';

    const module=document.createElement('atlas-badge');
    module.setAttribute('tone','info');
    module.textContent=entry.bundle.moduleCode;
    meta.append(module);

    if (entry.task.priority) {
      const priority=document.createElement('span');
      priority.className='atlas-muted';
      priority.textContent=entry.task.priority;
      meta.append(priority);
    }

    if (entry.task.dueDate) {
      const due=document.createElement('span');
      due.className='atlas-muted';
      due.textContent='Due '+entry.task.dueDate;
      meta.append(due);
    }

    row.append(rank,main,meta);
    root.append(row);
  });
});
